def parse_duration(text):
    text = text.strip()
    if not text:
        raise ValueError("empty duration")
    if text.isdigit():
        return int(text)
    hours, h, rest = text.partition("h")
    if not h:
        hours, rest = "0", text
    minutes = 0
    if rest:
        if not rest.endswith("m"):
            raise ValueError(f"bad duration: {text!r}")
        minutes = int(rest[:-1])
    return int(hours) * 60 + minutes

assert parse_duration("1h30m") == 90
assert parse_duration("45m") == 45
```
The empty string needs its own check (otherwise it would quietly mean 0 minutes); `int("")` raises `ValueError`, which covers `"h"` and `"m"`; `"30m1h"` fails because `int("30m1")` raises.

