import numpy as np

def signed_area(p, q, r):
    M = np.column_stack([np.subtract(q, p), np.subtract(r, p)]).astype(float)
    return np.linalg.det(M) / 2

def triangle_area(p, q, r):
    return abs(signed_area(p, q, r))

def polygon_area(points):
    p0 = points[0]
    total = sum(signed_area(p0, points[i], points[i + 1]) for i in range(1, len(points) - 1))
    return abs(total)

