def _sort_count(nums):
    if len(nums) < 2:
        return list(nums), 0
    mid = len(nums) // 2
    a, left = _sort_count(nums[:mid])
    b, right = _sort_count(nums[mid:])
    out, i, j, cross = [], 0, 0, 0
    while i < len(a) and j < len(b):
        if a[i] <= b[j]:
            out.append(a[i]); i += 1
        else:
            out.append(b[j]); j += 1
            cross += len(a) - i
    return out + a[i:] + b[j:], left + right + cross

def count_inversions(nums):
    return _sort_count(nums)[1]

