from pathlib import Path

def build_report(rows, source, generated):
    students, topics = {}, {}
    for r in rows:
        s = students.setdefault(r["student_id"], {"done": 0, "total": 0, "scores": [], "open": []})
        s["total"] += 1
        if r["completed"]:
            s["done"] += 1
        else:
            s["open"].append(r["lesson"])
        if r["score"] is not None:
            s["scores"].append(r["score"])
        t = topics.setdefault(r["topic"], {"done": 0, "lessons": 0, "scores": []})
        t["lessons"] += 1
        t["done"] += int(r["completed"])
        if r["score"] is not None:
            t["scores"].append(r["score"])

    def mean(xs):
        return round(sum(xs) / len(xs), 1) if xs else None

    return {
        "generated": generated,
        "source": str(source),
        "students": [
            {"id": sid, "rate": round(s["done"] / s["total"], 3), "mean_score": mean(s["scores"]), "open": s["open"]}
            for sid, s in sorted(students.items())
        ],
        "topics": [
            {"topic": name, "done": t["done"], "lessons": t["lessons"],
             "rate": round(t["done"] / t["lessons"], 3), "mean_score": mean(t["scores"])}
            for name, t in sorted(topics.items())
        ],
    }

def write_json(report, path):
