        x, j = a[i], i - 1
        while j >= 0 and a[j] > x:
            a[j + 1] = a[j]
            j -= 1
        a[j + 1] = x
    return a

def merge_sort(nums):
    if len(nums) < 2:
        return list(nums)
    mid = len(nums) // 2
    a, b = merge_sort(nums[:mid]), merge_sort(nums[mid:])
    out, i, j = [], 0, 0
    while i < len(a) and j < len(b):
        if a[i] <= b[j]:
            out.append(a[i]); i += 1
        else:
            out.append(b[j]); j += 1
    return out + a[i:] + b[j:]

def quicksort(nums):
    if len(nums) < 2:
        return list(nums)
    p, rest = nums[0], nums[1:]
    return quicksort([x for x in rest if x < p]) + [p] + quicksort([x for x in rest if x >= p])

rng = random.Random(0)
n = 2000
rand = [rng.randint(0, 10**6) for _ in range(n)]
srt = sorted(rand)
nearly = list(srt)
for _ in range(20):
    i, j = rng.randrange(n), rng.randrange(n)
    nearly[i], nearly[j] = nearly[j], nearly[i]

print(f"{'sort':<10}{'random':>10}{'sorted':>10}{'nearly':>10}")
for name, fn in [("insertion", insertion_sort), ("merge", merge_sort), ("quick", quicksort), ("builtin", sorted)]:
    cells = []
    for data in (rand, srt, nearly):
        t = time.perf_counter()
        assert fn(data) == srt
        cells.append((time.perf_counter() - t) * 1000)
    print(f"{name:<10}" + "".join(f"{c:>10.1f}" for c in cells))
